#!/bin/bash -l
#SBATCH --output=/puffin/logs/run_puffin%j.out --array=1-24 --ntasks=1 --cpus-per-task=8 --mem=64GB --time=0-5:00:00 --mail-type=END,FAIL

# Datasets generated by the T2T build script
#  "T2T_forward"
#  "T2T_reversed"
#  "dinucleotide_shuffled/global"
#  "dinucleotide_shuffled/local"
#  "mononucleotide_shuffled/global"
#  "mononucleotide_shuffled/local"
#  "repeat_mononucleotide_global_shuffled"
#  "nonrepeat_mononucleotide_global_shuffled"
#  "repeat_reversed"
#  "nonrepeat_reversed"
#  "holdout/forward"
#  "holdout/reversed"

# Run once for each dataset
dataset_dir="T2T_forward"
out_dir="./puffin_outputs/T2T Forward"
dataset_file=$(ls $dataset_dir | sed -n "${SLURM_ARRAY_TASK_ID}p")
python puffin_D.py sequence "$dataset_dir/$dataset_file"
mv *.npy "$out_dir"
